            {"title": "Directive (EU) 2024/825 (EmpCo)", "url": "https://eur-lex.europa.eu/legal-content/EN/TXT/HTML/?uri=CELEX:32024L0825", "tier": "S", "published": "Mar 2024, applies Sep 2026"},
